// Generated by `dokimos verification scaffold` from plan VP-B1-APPROVAL. Each body fails until
// it is written; `dokimos verification coverage` reports DOKIMOS-UNIMPLEMENTED as a placeholder.
namespace Approval.Tests

open System
open System.IO
open System.Net
open System.Net.Http
open System.Net.Sockets
open Xunit
open Approval

module APR006Tests =
    /// A response reduced to what the client can observe: status, every header and the body.
    type private Observed =
        { Label: string
          Status: HttpStatusCode
          Headers: (string * string) list
          Body: string }

    let private freePort () =
        let listener = new TcpListener(IPAddress.Loopback, 0)
        listener.Start()
        let port = (listener.LocalEndpoint :?> IPEndPoint).Port
        listener.Stop()
        port

    let private newTempDir () =
        let dir = Path.Combine(Path.GetTempPath(), "apr006-" + Guid.NewGuid().ToString("N"))
        Directory.CreateDirectory dir |> ignore
        dir

    let private observe label (response: HttpResponseMessage) =
        let headers =
            [ yield! response.Headers |> Seq.map (fun h -> h.Key, String.Join(",", h.Value))
              yield! response.Content.Headers |> Seq.map (fun h -> h.Key, String.Join(",", h.Value)) ]

        { Label = label
          Status = response.StatusCode
          Headers = headers
          Body = response.Content.ReadAsStringAsync().Result }

    let private get (client: HttpClient) label (path: string) =
        client.GetAsync(path).Result |> observe label

    let private post (client: HttpClient) label (path: string) (fields: (string * string) list) =
        let content =
            new FormUrlEncodedContent(fields |> List.map (fun (k, v) -> Collections.Generic.KeyValuePair(k, v)))

        client.PostAsync(path, content).Result |> observe label

    let private assertNoToken (token: string) (o: Observed) =
        Assert.False(o.Body.Contains(token, StringComparison.Ordinal), sprintf "[%s] token found in body" o.Label)

        o.Headers
        |> List.iter (fun (name, value) ->
            Assert.False(
                name.Contains(token, StringComparison.Ordinal) || value.Contains(token, StringComparison.Ordinal),
                sprintf "[%s] token found in header %s" o.Label name
            ))

    let private location (o: Observed) =
        o.Headers
        |> List.tryFind (fun (k, _) -> String.Equals(k, "Location", StringComparison.OrdinalIgnoreCase))
        |> Option.map snd
        |> Option.defaultWith (fun () -> failwithf "[%s] no Location header" o.Label)

    let private hasTestId testId (o: Observed) =
        o.Body.Contains(sprintf "data-testid=\"%s\"" testId) || o.Body.Contains(sprintf "data-testid='%s'" testId)
        || o.Body.Contains(sprintf "data-testid=%s" testId)

    /// APR-006-O1: the token's value never appears in any HTTP response body, response header or stored request file, including error pages.
    [<Fact>]
    let ``APR-006-O1`` () : unit =
        let token = "apr006-secret-" + Guid.NewGuid().ToString("N")
        let dir = newTempDir ()
        let store = FileStore(dir)
        let baseUrl = sprintf "http://127.0.0.1:%d" (freePort ())
        let app = Web.build store token baseUrl
        app.StartAsync().Wait()

        try
            use handler = new HttpClientHandler(AllowAutoRedirect = false)
            use client = new HttpClient(handler, BaseAddress = Uri(baseUrl))
            let get = get client
            let post = post client

            let home = get "GET /" "/"
            Assert.Equal(HttpStatusCode.OK, home.Status)
            Assert.True(hasTestId "create" home, "home page has the create form")

            let created = post "POST /requests" "/requests" [ "title", "Token confinement check" ]
            Assert.Equal(HttpStatusCode.SeeOther, created.Status)
            let requestPath = location created |> fun l -> Uri(Uri(baseUrl), l).AbsolutePath
            Assert.StartsWith("/requests/", requestPath)
            let id = requestPath.Substring("/requests/".Length)
            let commandPath = requestPath + "/command"

            let page0 = get "GET request (Draft)" requestPath
            Assert.Equal(HttpStatusCode.OK, page0.Status)
            Assert.True(hasTestId "state" page0)

            let submitted = post "Submit v0" commandPath [ "command", "Submit"; "note", ""; "version", "0" ]
            Assert.Equal(HttpStatusCode.SeeOther, submitted.Status)

            // Illegal command in Submitted -> 422 with the error marker.
            let illegal = post "Submit again (illegal)" commandPath [ "command", "Submit"; "note", ""; "version", "1" ]
            Assert.Equal(enum<HttpStatusCode> 422, illegal.Status)
            Assert.True(hasTestId "error" illegal, "422 page shows [data-testid=error]")

            // Stale version -> 409 with the conflict marker.
            let stale = post "Approve at stale v0" commandPath [ "command", "Approve"; "note", "stale"; "version", "0" ]
            Assert.Equal(HttpStatusCode.Conflict, stale.Status)
            Assert.True(hasTestId "conflict" stale, "409 page shows [data-testid=conflict]")

            let approved = post "Approve v1" commandPath [ "command", "Approve"; "note", "approved note"; "version", "1" ]
            Assert.Equal(HttpStatusCode.SeeOther, approved.Status)

            let page2 = get "GET request (Approved)" requestPath
            Assert.Equal(HttpStatusCode.OK, page2.Status)
            Assert.Contains("approved note", page2.Body)

            // Unknown ids and unknown routes are errors, and must not leak either.
            let unknownId = get "GET unknown id" "/requests/00000000000000000000000000000000"
            Assert.False(int unknownId.Status >= 200 && int unknownId.Status < 300, "unknown id is not a success")

            let unknownCommand =
                post "command on unknown id" "/requests/00000000000000000000000000000000/command" [ "command", "Submit"; "note", ""; "version", "0" ]

            Assert.False(int unknownCommand.Status >= 200 && int unknownCommand.Status < 300)

            let unknownRoute = get "GET unknown route" "/no/such/route"
            let garbage = post "garbage command" commandPath [ "command", "Bogus"; "version", "x" ]

            [ home; created; page0; submitted; illegal; stale; approved; page2; unknownId; unknownCommand; unknownRoute; garbage ]
            |> List.iter (assertNoToken token)

            // Stored request files never contain the token.
            let files = Directory.GetFiles(dir, "*.json", SearchOption.AllDirectories)
            Assert.Contains(Path.Combine(dir, id + ".json"), files)

            files
            |> Array.iter (fun f ->
                Assert.False(File.ReadAllText(f).Contains(token, StringComparison.Ordinal), sprintf "token found in %s" f))

            Directory.GetFiles(dir, "*", SearchOption.AllDirectories)
            |> Array.iter (fun f ->
                Assert.False(File.ReadAllText(f).Contains(token, StringComparison.Ordinal), sprintf "token found in %s" f))
        finally
            app.StopAsync().Wait()
            (app :> IAsyncDisposable).DisposeAsync().AsTask().Wait()
            try Directory.Delete(dir, true) with _ -> ()
